function el(tag,cls){const n=document.createElement(tag);if(cls)n.className=cls;return n;}
function append(parent,...nodes){for(const n of nodes)if(n)parent.append(n);}
function view(c,s){return {id:c?.id||'skirmish',s,mode:c?'campaign':'skirmish',c,preparing:c?s.stage==='pre-battle':s.stage==='setup'};}
