 const panels=new Map();for(const [tab,en,ko]of tabs){const b=el('button');b.type='button';b.id=id+'-tab-'+tab;b.dataset.bpTab=tab;b.setAttribute('role','tab');b.setAttribute('aria-controls',id+'-panel-'+tab);b.innerHTML=L(en,ko);nav.append(b);const p=el('section','bp-tab-panel');p.id=id+'-panel-'+tab;p.dataset.bpPanel=tab;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',b.id);p.tabIndex=0;panels.set(tab,p);}
