  const layout=el('div','bp-side-content'),cards=el('div','bp-unit-panels'),buttons=[];
  for(const {row,reserve}of rows){const f=g?.fighters.find(f=>f.id===row.fighterId);if(!f)continue;const uid=String(row.fighterId),item=el('article','bp-unit-row'),unitHeading=el('h2','bp-unit-name'),tab=el('button','bp-unit-toggle');tab.type='button';tab.dataset.bpUnit=uid;tab.id=id+'-unit-toggle-'+i+'-'+buttons.length;tab.setAttribute('aria-controls',id+'-unit-'+i+'-'+buttons.length);tab.innerHTML=`<span data-user-text>${E(f.name)}</span>${reserve?`<small>${L('Reserve','증원 대기')}</small>`:''}<img class="bp-icon bp-unit-chevron" src="/icons/chevron-down.svg" alt="">`;unitHeading.append(tab);item.append(unitHeading);buttons.push(tab);

   let panel=originals.find(n=>n.dataset.bpSide===String(i)&&n.dataset.bpFighter===uid);if(panel){panel.open=true;panel.querySelector(':scope > summary')?.setAttribute('hidden','');}else{panel=el('section');panel.innerHTML=window.MMPlayMode?.card(unitView(f,row),g)||'';}
   panel.classList.add('bp-unit-panel');panel.dataset.bpUnitPanel=uid;panel.id=tab.getAttribute('aria-controls');panel.setAttribute('role','region');panel.setAttribute('aria-labelledby',tab.id);
   if(reserve){const badge=el('p','bp-reserve-label');badge.innerHTML=L('Reserve deck','증원 대기');panel.prepend(badge);}
   panel.querySelector('.pm-status')?.remove();

   for(const fold of panel.querySelectorAll('.pm-collapsible[data-play-section]')){const k=JSON.stringify([i,uid,fold.dataset.playSection]);fold.open=ui.sections.get(k)||false;fold.addEventListener('toggle',()=>{if(fold.isConnected)ui.sections.set(k,fold.open);});}
   item.append(panel);cards.append(item);
  }
  if(!cards.children.length){const empty=el('p','bp-empty');empty.innerHTML=L('No crew entered','크루 명단 미입력');cards.append(empty);}
  layout.append(cards);team.append(layout);bodies.append(team);
  const selectUnit=(unit,toggle=false)=>{if(unit!==null&&!buttons.some(t=>t.dataset.bpUnit===unit))unit=buttons[0]?.dataset.bpUnit??null;if(toggle&&ui.units[i]===unit)unit=null;ui.units[i]=unit;for(const t of buttons){const on=t.dataset.bpUnit===unit;t.setAttribute('aria-expanded',String(on));t.closest('.bp-unit-row').classList.toggle('is-open',on);}for(const card of cards.querySelectorAll('[data-bp-unit-panel]'))card.hidden=card.dataset.bpUnitPanel!==unit;};
