 const results=el('section','card'),h=el('h2'),summary=el('p'),winners=b.winners?.length?b.winners:[b.winner].filter(Boolean);h.innerHTML=L('Battle result','전투 결과');summary.dataset.userText='';summary.textContent=b.isDraw?txt('Draw','무승부'):winners.length?winners.map(id=>gangFor(id)?.name||id).join(', '):txt('Result not recorded','결과 미입력');results.append(h,summary);
 for(const p of b.participants||[]){if(!p.sideJob&&!p.sideJobName)continue;const row=el('p');row.dataset.userText='';row.textContent=(gangFor(p.gangId||p.gang_id)?.name||'—')+' · '+(p.sideJobName||p.sideJob)+(p.sideJobCompleted?' · '+txt('Achieved','달성'):'');results.append(row);}
 const canEdit=()=>campaign()?.id===c.id&&campaign().battles?.includes(b)&&!!window.MMCampaignAutomation?.canEdit(campaign());
 const result=el('button','btn primary');result.type='button';result.dataset.bpReportResult='';result.innerHTML=b.status==='Played'?L('Edit result','결과 수정'):L('Record result','결과 반영');result.disabled=!canEdit();result.addEventListener('click',()=>{if(!canEdit())return;cpReportModal(b);const played=document.querySelector('#modal-form [name="battlePlayed"]');if(played){played.checked=true;played.dispatchEvent(new Event('change',{bubbles:true}));}});results.append(result);ctx.panels.get('round').append(results);
 const operations=el('section','card'),notes=el('p'),edit=el('button','btn');notes.dataset.userText='';notes.style.whiteSpace='pre-wrap';notes.textContent=b.notes||txt('No battle notes','전투 메모 없음');edit.type='button';edit.dataset.bpReportEdit='';edit.innerHTML=L('Edit battle details','전투 설정 수정');edit.disabled=!canEdit();edit.addEventListener('click',()=>{if(canEdit())cpReportModal(b);});operations.append(notes,edit);ctx.panels.get('operations').append(operations);window.UKI18n?.refresh(root);
