window.addEventListener('click',event=>{const button=event.target.closest?.('[data-cp="crew-select"]');if(!button||button.disabled)return;const c=typeof campaign==='function'&&campaign(),s=c?.sessions?.find(s=>s.id===button.dataset.sid);if(!c||!s?.automationPreparation||s.stage!=='pre-battle'||!window.MMCampaignPreparation?.supported(c)||!window.MMCampaignSessionData?.canEdit(c))return;event.preventDefault();event.stopImmediatePropagation();window.MMCampaignPreparation.handle('edit',c,{caId:s.id});},true);
